#!/bin/zsh
# Saison 2 : les 11 autres scènes refaites avec les vues en pied du héros (hero_s2/sel_*.png), tourné vers son
# interlocuteur, avec une expression précise, plus de sourire figé (demande de Stéphan du 24/11).
# FLUX 3 Klein local, file calcul-lourd. Relançable : saute ce qui existe. Usage : gen_s2_scenes_vues2.sh [id…]
cd "$(dirname "$0")/../work/crossover" || exit 1
ST="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame, no text, no letters"
STL="hand-painted 2000s 2D point-and-click adventure game scene, painterly detailed backgrounds like classic adventure games, bold dark outlines, warm saturated colors, humorous storybook fantasy, characters with realistic adult proportions and ironic expressions, wide composition, no logo, no watermark, no frame"
H="The hero is exactly the man from the reference picture: same face, same blond ponytail, same horned iron Viking helmet, same fur-collared studded leather armor, same round wooden shield strapped on his back, same pleated brown leather kilt with leather pouches, same fur-topped boots, same painted style; NOT a tartan kilt. His usual smirk is gone, no smile at all."
L34="He is seen in three-quarter view, his chest, feet and face turned toward the LEFT side of the picture"
R34="He is seen in three-quarter view, his chest, feet and face turned toward the RIGHT side of the picture"
VIL="a blocky villager made entirely of big square cubes, with a huge long rectangular nose, a single bushy unibrow, a long brown robe and his arms folded together in front of him"
CR="a tall green creature made of cubes, with four short stubby block legs, no arms and a sad dark pixel face"
DOC="a tall lanky old scientist with realistic adult proportions and a normal-sized head, a shock of wild white hair, wide excited eyes, a white lab coat over a dark shirt, protective goggles pushed up on his forehead"
HO="a sardonic doctor in his late forties with short messy dark brown hair, intense blue eyes and heavy stubble, a charcoal grey suit blazer over an open-collared light blue shirt with a white t-shirt underneath, dark trousers and sneakers, no lab coat, a bored contemptuous stare"
PA="a clean-shaven middle-aged paleontologist with short greying brown hair, a light straw wide-brimmed hat with a dark band, a long-sleeved blue denim shirt with rolled-up sleeves, a red bandana knotted around his neck, beige khaki trousers and brown boots"
AR="a weary medieval king in his forties with long messy dark curly hair falling to his shoulders, a thin ornate gold circlet diadem across his forehead instead of a crown, a short dark goatee and stubble, a dark burgundy red wool tunic, a dark brown studded leather cuirass with buckled shoulder straps and an embossed dragon motif, a black scarf at the neck, a sceptical sidelong glance"
PE="a lanky medieval knight in his forties with messy shoulder-length greying blond hair and a short scruffy beard, a blue quilted padded gambeson closed with leather tabs and laces, a grey wool hooded cloak fastened with a small brass clasp, brown laced leather bracers, a sword in a brown leather scabbard at his hip, a blank vacant stare"
KA="a stout round-faced medieval knight with short dark brown hair and a few days of stubble, a chainmail hauberk, a red wool cloak with a red hood collar draped over his shoulders, leather straps"
CO="a towering massively muscular barbarian with long straight light brown hair to his shoulders, a studded dark leather headband, a few black war paint stripes across his face and shoulders, bare tanned torso, a pendant necklace, a fur loincloth under a wide brown leather belt, dark leather wrist bracers, fur boots, his long sword strapped on his back, a stern stare"
KID="three boys of about twelve with realistic child proportions, bowl haircuts, one in a blue and white trucker cap, raglan t-shirts, jeans and sneakers, each holding a big walkie-talkie"
DX="a polite forensic analyst in his thirties with tousled light brown hair, a sly polite half-smile and calm watchful eyes, wearing a short-sleeved coral orange polo shirt with a chest pocket and a pair of sunglasses hooked in its open placket, khaki trousers"
MO="a calm tall bald Black man with dark brown skin, small round dark pince-nez sunglasses, a long dark green-black leather coat over a dark vest and tie"
AI="a large sleek white robotic artificial intelligence hanging down from the ceiling on a black mechanical arm, a smooth white head shell with a single round glowing yellow eye"
typeset -A P R
P[r_minecraftv]="$H $L34, toward the villager; he looks baffled: eyebrows raised high, mouth hanging open, staring at his own round hand held up in front of him. A strange sunny world where everything is made of big cubes: blocky square trees, cubic grass hills, a cubic sun, square clouds, a waterfall made of blue blocks. From left to right: first $VIL, talking to the hero; second the hero, holding an old wooden bucket of water in his other hand; third, right behind the hero's back, $CR, sneaking up on him silently. The hero himself stays round and hand-painted, not cubic. $ST"; R[r_minecraftv]=hero_s2/sel_34_left.png
P[r_retourv]="$H $L34, toward the scientist; he looks alarmed and sceptical: leaning back, eyes wide, eyebrows raised, teeth clenched in a nervous grimace. A small 1950s American town square at night in a thunderstorm: a courthouse with a big lit clock tower, lightning in the sky, a long cable stretched from the clock tower down to a lamp post. From left to right: first an old wooden medieval cart completely covered with shiny stainless steel panels, two doors opened upward like wings, glowing blue coils, harnessed to a brown horse; second $DOC, waving both arms excitedly at the hero; third the hero on the right. Each person wears only his own clothes. $ST"; R[r_retourv]=hero_s2/sel_34_left.png
P[r_potterv]="$H $L34, looking down at the old hat on the floor; he looks haughty: chin raised, eyelids half lowered, a disdainful pout. A great hall of a wizard school castle: long wooden tables, hundreds of floating candles, a starry enchanted ceiling, robed students staring. On a wooden stool in the centre, the hero sits wearing an old dented wooden bucket on his head over his helmet instead of a hat, while an old patched brown pointed wizard hat lies offended on the floor on the left beside the stool. $ST"; R[r_potterv]=hero_s2/sel_34_left.png
P[r_kaamelottv]="$H $R34, toward the king; he looks earnest and exasperated, explaining patiently: eyebrows raised, mouth open in mid-sentence, one open hand held out. A medieval castle hall with a big round wooden table covered with ham, sausages, round bread rolls and cheese, plain red banners without writing, torches. Four separate people around the table, from left to right: first the hero, sitting; second $AR, sitting with his chin on his hand, wearing no helmet; third $PE, standing; fourth $KA, sitting, holding a small knife topped with pate in one hand and a bread roll in the other, about to eat. Each person wears only his own clothes. $ST"; R[r_kaamelottv]=hero_s2/sel_34_right.png
P[r_conanv]="$H He is seen in strict side profile facing LEFT, leaning far forward, pushing a wooden beam with both hands and his chest; his face shows exhausting strain: teeth gritted, eyes squeezed half shut, red cheeks, drops of sweat. A barren snowy plain under a grey sky. In the centre, a big horizontal wooden mill capstan: a thick wooden post with four long horizontal wooden beams at waist height, and a circular path worn into the snow around it. Two separate people push two different beams, walking in a circle around the post: $CO on the far side behind the post, walking to the right, pushing his beam with ease; and the hero in the foreground on the near side, walking to the left. Each person wears only his own clothes. In the sky flies a long wingless dragon shaped like a snake, covered in white fur and pearly pink scales, with a big friendly dog-like head and floppy ears. On the horizon, a dark swirling void of nothingness eats the landscape. $ST"; R[r_conanv]=hero_s2/sel_profile_left.png
P[r_housev]="$H $L34, toward the doctor; he looks worried: eyebrows drawn up in the middle, mouth tight, one hand on his chest. A 2000s hospital diagnostic office with glass walls, a big whiteboard on which only the word LUPUS is written in large marker letters and crossed out with a big red line, a light box with x-rays. Two separate people, from left to right: first $HO, standing upright, his right hand resting palm down on top of the curved crook handle of a dark wooden walking cane whose tip stands on the floor beside his foot (the cane reaches his hip, about half his height), his left index finger pointing at the hero; second the hero on the right, sitting on the edge of a hospital bed in his armor. Each person wears only his own clothes. No other writing anywhere. $STL"; R[r_housev]=hero_s2/sel_34_left.png
P[r_jurassicv]="$H $L34, toward the paleontologist; he is frozen stiff with terror: eyes wide, lips pressed tight, holding his breath, a drop of sweat on his brow. Night in a rainy tropical jungle in front of a tall broken electric fence with sparks. From left to right: first $PA, crouching low beside an old wooden cart, one finger on his lips; second the hero, sitting rigid in the old wooden cart, an old wooden bucket of water on the bench beside him, the water in the bucket rippling in perfect circles; behind the trees on the right, a gigantic toothy dinosaur head looming in the dark, lit by lightning. Each person wears only his own clothes. $ST"; R[r_jurassicv]=hero_s2/sel_34_left.png
P[r_strangerv]="$H $L34, toward the kids; he looks confused: frowning, one eyebrow lowered, scratching his helmet with one hand. A cozy 1980s suburban living room at night with wood-paneled walls. On the back wall on the right, painted in neat black capital letters, three tidy rows of the alphabet: ABCDEFGHI on the first row, JKLMNOPQR on the second row, STUVWXYZ on the third row, with a string of colorful Christmas lights above, one bulb above each letter, a few glowing. No other writing anywhere. A floral sofa, a box TV. From left to right: first $KID, staring at the hero; second the hero in the middle of the room; behind him on the far right, the wallpaper torn open, and a tall slimy creature whose head opens like the petals of a flower pokes out of the wall. $STL"; R[r_strangerv]=hero_s2/sel_34_left.png
P[r_dexterv]="$H $R34, toward the analyst; he looks uneasy: a nervous sideways glance at the analyst, a forced tight-lipped grimace, a bead of sweat on his temple. A tidy sunny Miami police forensic lab: microscopes, glass slides, a window showing palm trees and the sea. In the background, a small room covered in clear plastic sheeting. Two separate people, from left to right: first the hero; second $DX, holding an open box of donuts in one hand and a magnifying glass in the other, studying pink raspberry jam splatters mixed with birthday cake crumbs on the hero's armor. Each person wears only his own clothes. $ST"; R[r_dexterv]=hero_s2/sel_34_right.png
P[r_matrixv]="$H $R34, toward the man in the leather coat; he looks greedy: eyes wide and fixed on the red bottle, eyebrows raised, mouth open with eagerness. A dark shabby room with a red leather armchair, lit by green light, with columns of glowing green falling symbols in the background windows. Two separate people, from left to right: first the hero, already holding one small blue potion bottle in one hand and reaching with his other hand toward the red one; second $MO, facing the hero, one small red potion bottle lying on his open left palm. Exactly two potion bottles in the whole picture. Each person wears only his own clothes. $ST"; R[r_matrixv]=hero_s2/sel_34_right.png
P[r_portalv]="$H He is seen in strict side profile facing RIGHT, bent forward, pushing a big wheel of yellow cheese with both hands onto a round floor button on the right; he frowns with effort and glances up suspiciously at the robot, eyes narrowed. A sterile white futuristic test chamber with clean white wall panels and grey floor, one glowing blue oval portal on the left wall and one glowing orange oval portal on the right wall. On a white pedestal sits a big birthday cake with a single candle. Above the hero, $AI, watching him. $ST"; R[r_portalv]=hero_s2/sel_profile_right.png
# 2e passe : Matrix avait trois fioles (une rouge en trop dans la main du héros). Le héros prend les deux, comme dans le chapitre.
P[r_matrixw]="$H $R34, toward the man in the leather coat; he looks greedy: eyes wide, eyebrows raised, mouth open with eagerness. A dark shabby room with a red leather armchair, lit by green light, with columns of glowing green falling symbols in the background windows. Two separate people, from left to right: first the hero, reaching out greedily with both of his EMPTY open hands toward the two bottles at once; second $MO, facing the hero, holding out both open palms: one small red potion bottle on his left palm and one small blue potion bottle on his right palm. The hero holds nothing in his hands. Exactly two potion bottles in the whole picture, both on the man's palms. Each person wears only his own clothes. $ST"; R[r_matrixw]=hero_s2/sel_34_right.png
# 2e passe (25/11) : les trois garçons étaient des clones. Chacun son allure emblématique, dans l'ordre, chacun ses vêtements.
KW="a small slight shy boy of about twelve with a dark brown bowl haircut and a worried look, a faded red-and-brown plaid flannel shirt buttoned over a white t-shirt, a worn tan corduroy jacket, jeans"
KD="a chubby round-faced boy of about twelve with curly brown hair bursting out from under a yellow and green trucker cap, a big gap-toothed grin with missing front teeth, a grey raglan baseball t-shirt with navy blue sleeves under an open red puffy vest, jeans"
KM="a tall thin lanky boy of about twelve, taller than the other two, pale with freckles, shaggy straight black hair with a long fringe, a brown plaid button-up shirt open over a striped long-sleeve shirt, jeans"
P[r_strangerw]="$H $L34, toward the kids; he looks confused: frowning, one eyebrow lowered, scratching his helmet with one hand. A cozy 1980s suburban living room at night with wood-paneled walls. On the back wall on the right, painted in neat black capital letters, three tidy rows of the alphabet: ABCDEFGHI on the first row, JKLMNOPQR on the second row, STUVWXYZ on the third row, with a string of colorful Christmas lights above, one bulb above each letter, a few glowing. No other writing anywhere. A floral sofa, a box TV. Three clearly different boys stand on the left, staring at the hero, each holding a big walkie-talkie, each wearing only his own clothes, different heights, different faces, different hair: from left to right, first $KM; second $KD; third $KW. Then the hero in the middle of the room; behind him on the far right, the wallpaper torn open, and a tall slimy creature whose head opens like the petals of a flower pokes out of the wall. $STL"; R[r_strangerw]=hero_s2/sel_34_left.png
# 3e passe (25/11) : version 2 retenue, mais la bouche du garçon à casquette était mal dessinée : sourire bouche fermée.
KD2="a chubby round-faced boy of about twelve with curly brown hair bursting out from under a plain yellow and green trucker cap with no writing and no logo on it, a big cheerful closed-mouth smile with rosy cheeks, a grey raglan baseball t-shirt with navy blue sleeves under an open red puffy vest, jeans"
P[r_strangerx]="${P[r_strangerw]/$KD/$KD2}"; R[r_strangerx]=hero_s2/sel_34_left.png
ids=("$@"); [ ${#ids} -eq 0 ] && ids=(r_minecraftv r_retourv r_potterv r_kaamelottv r_conanv r_housev r_jurassicv r_strangerv r_dexterv r_matrixv r_portalv)
for id in $ids; do
  for s in ${=SEEDS:-1 2}; do
    out="${id}_$s.png"; [ -f "$out" ] && continue
    seed=$(( ${#id} * 1000 + s * 137 + 6161 ))
    flux-image "${P[$id]}" -i "${R[$id]}" -s 1280x720 --seed $seed -o "$out" >/dev/null 2>&1
    echo "$(date +%H:%M:%S) ok $out"
  done
done
